#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "doitgen.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and C4 with the same values as the original C code.
 *
 * Original C layout:
 *   A[NR][NQ][NP]  accessed as A[i][j][k]
 *   C4[NP][NP]     accessed as C4[i][j]
 *
 * Halide layout:
 *   A(p, q, r)  with Buffer size (NP, NQ, NR)
 *     mapping: A(p, q, r) == A_c[r][q][p]
 *
 *   C4(p, s) with Buffer size (NP, NP)
 *     mapping: C4(p, s) == C4_c[s][p]
 */
static void init_array(int nr, int nq, int np,
                       Halide::Buffer<num_t, 3> A,
                       Halide::Buffer<num_t, 2> C4) {
    Var p("p"), q("q"), r("r");
    Var i("i"), j("j");

    Func init_A("init_A"), init_C4("init_C4");

    // Precompute 1/np as a constant Expr of the right type so we can
    // use a multiplication instead of a division in the inner loops.
    Expr np_i   = cast<int>(np);
    Expr inv_np = cast<num_t>(1) / np_i;

    // A[i][j][k] = ((i*j + k) % np) / np;
    // Mapping: i -> r, j -> q, k -> p  =>  A(p, q, r)
    init_A(p, q, r) =
        cast<num_t>(((r * q + p) % np_i)) * inv_np;

    // C4[i][j] = ((i*j) % np) / np;
    // Mapping: i -> j (second index), j -> i (first index) => C4(first=j, second=i)
    init_C4(i, j) =
        cast<num_t>(((j * i) % np_i)) * inv_np;

    // -------------------------
    // Initialization schedules
    // -------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // For A: r is the slowest-varying (image "depth"), q is middle,
    // p is innermost and contiguous. Parallelize across r (NR) and
    // vectorize across p (NP) for good cache and SIMD utilization.
    init_A
        .reorder(p, q, r)   // p innermost, matches memory layout
        .parallel(r)        // distribute rows of (q,p) across cores
        .vectorize(p, vec_width);

    // For C4: i is innermost and contiguous, j is outer. Again,
    // parallelize outer j and vectorize inner i.
    init_C4
        .reorder(i, j)
        .parallel(j)
        .vectorize(i, vec_width);

    // JIT-compile-and-run the initializers.
    init_A.realize(A);
    init_C4.realize(C4);
}

int main(int argc, char *argv[]) {
    // Problem size (from doitgen.hpp / PolyBench)
    int nr = NR;
    int nq = NQ;
    int np = NP;

    // Buffers corresponding to:
    //   A[NR][NQ][NP] -> A(np, nq, nr)  (p, q, r)
    //   C4[NP][NP]    -> C4(np, np)
    Halide::Buffer<num_t, 3> A(np, nq, nr);
    Halide::Buffer<num_t, 2> C4(np, np);

    // Initialize data
    init_array(nr, nq, np, A, C4);

    // ImageParams for Halide pipeline
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam C4_param(type_of<num_t>(), 2, "C4_param");

    A_param.set(A);
    C4_param.set(C4);

    // Vars and RDom
    Var p("p"), q("q"), r("r");
    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    // Pure definition: initialize the reduction result to 0.
    doitgen(p, q, r) = cast<num_t>(0);

    // Update definition: perform the dot-product reduction over s.
    doitgen(p, q, r) += A_param(s, q, r) * C4_param(p, s);

    // -------------------------
    // Schedule for main kernel
    // -------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Pure step:
    //   - We keep p innermost so that writes to A_out are contiguous.
    //   - Parallelize across r (NR), which is large and independent.
    //   - Vectorize across p to exploit SIMD.
    doitgen
        .reorder(p, q, r)   // explicit for clarity; p innermost
        .parallel(r)        // outermost parallel loop over r
        .vectorize(p, vec_width);

    // Reduction update step:
    //   - Mirror the parallelism and vectorization of the pure step.
    //   - RDom loop over 's' remains innermost; we compute multiple
    //     p values in SIMD for each 's' iteration.
    doitgen.update()
        .parallel(r)
        .vectorize(p, vec_width);

    // Bind JIT and compile
    doitgen.compile_jit(target);

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
