    // Sum over 's' corresponds to the inner-most loop over NP
    RDom s(0, A.dim(0).extent(), "s");  // A.dim(0).extent() == np

    // Main computation:
    // For each (r, q, p):
    //   A_new[r][q][p] = sum_{s=0..NP-1} A_old[r][q][s] * C4[s][p]
    //
    // Mapping to Halide:
    //   A_old[r][q][s] -> A_param(s, q, r)
    //   C4[s][p]       -> C4_param(p, s)
    Func doitgen("doitgen");

    // Pure definition: initialize accumulator
    doitgen(p, q, r) = cast<num_t>(0);

    // Update definition: reduction over s
    // Hoist A_param(s,q,r) into a temporary Expr so that when we
    // reorder loops (see schedule below), we read each A value once
    // per (r,q,s) and reuse it across all p.
    Expr a_val = A_param(s, q, r);
    doitgen(p, q, r) += a_val * C4_param(p, s);

    // --------------------------- Schedule ---------------------------
    // We target a modern x64 CPU: exploit both parallelism and SIMD.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Compute the whole 3D result at root.
    doitgen.compute_root();

    // Layout reminder:
    //   Buffer(A_out) is (p, q, r) => p is innermost/contiguous.
    // Default pure loop order would be: for r, for q, for p.
    // We keep that nesting but:
    //   - parallelize across 'r' (outermost)
    //   - vectorize across 'p' (innermost, contiguous)
    doitgen
        .parallel(r)
        .vectorize(p, vec_width);

    // For the reduction update:
    //
    // Default loop nest (conceptually) would be:
    //   for r:
    //     for q:
    //       for p:
    //         for s:
    //           doitgen(p,q,r) += A(s,q,r) * C4(p,s);
    //
    // This is poor for C4: inner loop walks s while p is fixed,
    // and with our storage C4(p,s) that means a large stride in
    // memory (slow) and re-reading the same A(s,q,r) NP times (once
    // per p).
    //
    // We want instead:
    //   for r (parallel):
    //     for q:
    //       for s:
    //         load a_val = A(s,q,r);
    //         for p (vectorized, contiguous):
    //           doitgen(p,q,r) += a_val * C4(p,s);
    //
    // i.e. loop order: r -> q -> s -> p
    // which we express via reorder(p, s, q, r) (arguments are from
    // innermost to outermost).
    doitgen.update()
        .reorder(p, s, q, r)
        .parallel(r)              // outermost dimension: distribute planes over threads
        .vectorize(p, vec_width); // innermost: SIMD on contiguous p
    // ----------------------------------------------------------------

    // Bind JIT and compile
    doitgen.compile_jit();

    // Measure execution time of the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Realize into a new buffer A_out with same layout as A
    Halide::Buffer<num_t, 3> A_out(np, nq, nr);
    doitgen.realize(A_out);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int r_idx = 0; r_idx < nr; r_idx++) {
            for (int q_idx = 0; q_idx < nq; q_idx++) {
                for (int p_idx = 0; p_idx < np; p_idx++) {
                    // Mapping back to A[r][q][p] -> A_out(p, q, r)
                    std::cerr << A_out(p_idx, q_idx, r_idx) << '\n';
                }
            }
        }
    }

    // Print kernel execution time in seconds, with 6 decimal places
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
